srcDoc.css:
:root{--bg:#FFFFFF;--card:#FFFFFF;--ground:#F7F7F8;--ink:#1D1D1F;--muted:#6E6E73;--faint:#A1A1A6;--line:#E5E5EA;--line-strong:#D2D2D7;
--accent:#FFC400;--accent-hover:#F2B900;--accent-soft:#FFF6D6;--accent-ink:#8A6500;--ok:#1E7A46;--ok-soft:#E3F3E9;--warn:#9A5B00;--warn-soft:#FFF1D6;--bad:#B42318;--bad-soft:#FBE9E7;--info-soft:#EEF2F7;
--c1:#D99A00;--c2:#2E6FD6;--c3:#1FA463;--c4:#7B5CC7;--c5:#D9532B;
--display:'Manrope',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;--body:'Onest',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
--r:18px;--r-s:11px;--shadow:0 1px 2px rgba(0,0,0,.04),0 12px 32px -12px rgba(29,29,31,.14)}
*{box-sizing:border-box}
html,body{margin:0;background:transparent}
body{color:var(--ink);font-family:var(--body);font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--display)!important;margin:0;letter-spacing:-.01em;color:var(--ink)!important;font-weight:800}
a,a:visited,a:hover{color:inherit;text-decoration:none}
html,body{color:var(--ink)!important}
button{font:inherit;color:inherit}
.num{font-variant-numeric:tabular-nums}
:root[data-theme="dark"]{--bg:#000000;--card:#121212;--ground:#0A0A0A;--ink:#F5F5F7;--muted:#A1A1A6;--faint:#6E6E73;--line:#262626;--line-strong:#333336;
--accent:#FEC700;--accent-hover:#FFD43B;--accent-soft:#2A2200;--accent-ink:#FFD84D;--ok:#5BD08A;--ok-soft:#0F2A1B;--warn:#F0B35A;--warn-soft:#2A1E08;--bad:#F08A80;--bad-soft:#2B1512;--info-soft:#1A1F26;
--c1:#B98700;--c2:#4C86E0;--c3:#22A468;--c4:#8F73D9;--c5:#E8663F;--shadow:0 1px 2px rgba(0,0,0,.6),0 12px 32px -12px rgba(0,0,0,.8)}
:root[data-theme="dark"] .chip.on{background:var(--accent);color:#1D1D1F;border-color:var(--accent)}
:root[data-theme="dark"] .merchant .avatar{color:#1D1D1F}
.t{display:flex;align-items:center;height:40px}.t h2{font-size:22px;font-weight:800}

